#legend {
    position: absolute;
    right: 50px;
    top: 20px;
    z-index: 4;
}

#legend span {
    display: inline-block;
    font-size: 14px;
}

.legendIcon {
    width: 11px;
    height: 10px;
    /*-webkit-border-radius: 50%;*/
    /*-moz-border-radius: 50%;*/
    /*border-radius: 50%;*/
    margin: 0 7px;
}

.legendfont {
    margin-right: 23px;
}

.flowContainer {
    position: relative;
    padding-top: 38px;
}

.scrollContainer {
    width: 100%;
    height: 100%;
    overflow: scroll;
    position: relative;
    display: flex;
    justify-content: center;
    align-items: center;
}

.scrollContainer::-webkit-scrollbar {
    width: 4px;
    height: 4px
}

.svgContainer {
    flex-shrink: 0;
    position: absolute;
    /*与父容器左上顶齐*/
    top: -30px;
    left: 0;
}

.svg-vertical-position {
    position: relative;
    flex-shrink: 0;
}

.svg-center {
    position: relative;
}

.svg-scroll-position {
    position: absolute;
    top: 0;
    left: 0;
}

.svg-top {
    top: 0;
    position: absolute;
}

.svg-left {
    left: 0;
    position: absolute;
}
